package org.sleepwell.app;
import org.junit.Test;import static org.junit.Assert.*;
public final class AutoCloudBackupPolicyTest {
 @Test public void onlyRealNormallyEndedLocalTrackingIsEligible(){assertTrue(AutoCloudBackupPolicy.eligible(1,100,200,false,"tracked","local"));assertFalse(AutoCloudBackupPolicy.eligible(1,100,200,true,"tracked","local"));assertFalse(AutoCloudBackupPolicy.eligible(1,100,200,false,"manual","local"));assertFalse(AutoCloudBackupPolicy.eligible(1,100,200,false,"tracked","imported"));assertFalse(AutoCloudBackupPolicy.eligible(1,100,100,false,"tracked","local"));assertFalse(AutoCloudBackupPolicy.eligible(0,100,200,false,"tracked","local"));}
 @Test public void destinationRevisionAndImmutableRecordBoundsFormIdentity(){String a=AutoCloudBackupPolicy.key(1,100,200,1,"content://provider/tree/a");assertEquals(a,AutoCloudBackupPolicy.key(1,100,200,1,"content://provider/tree/a"));assertNotEquals(a,AutoCloudBackupPolicy.key(1,100,200,2,"content://provider/tree/a"));assertNotEquals(a,AutoCloudBackupPolicy.key(1,100,201,1,"content://provider/tree/a"));assertNotEquals(a,AutoCloudBackupPolicy.key(1,101,200,1,"content://provider/tree/a"));}
 @Test public void retriesAreBoundedOnlyBeforeCreate(){assertEquals("PENDING",AutoCloudBackupPolicy.failure(false,1));assertEquals("PENDING",AutoCloudBackupPolicy.failure(false,2));assertEquals("FAILED",AutoCloudBackupPolicy.failure(false,3));assertEquals("UNCERTAIN",AutoCloudBackupPolicy.failure(true,1));assertEquals("UNCERTAIN",AutoCloudBackupPolicy.failure(true,3));}
 @Test public void backoffDoesNotSpinOrOverflowSilently(){assertEquals(900001,AutoCloudBackupPolicy.retryAt(1,1));assertEquals(1800001,AutoCloudBackupPolicy.retryAt(1,2));assertEquals(3600001,AutoCloudBackupPolicy.retryAt(1,3));try{AutoCloudBackupPolicy.retryAt(Long.MAX_VALUE,1);fail();}catch(ArithmeticException expected){}}
 @Test public void permanentSizeLimitDoesNotMasqueradeAsProviderOutage(){assertTrue(AutoCloudBackupPolicy.oversized(new java.io.IOException("Export exceeds 8 MiB.")));assertTrue(AutoCloudBackupPolicy.oversized(new IllegalStateException(new IllegalArgumentException("Backup exceeds the 8 MB import limit."))));assertFalse(AutoCloudBackupPolicy.oversized(new java.io.IOException("Provider unavailable")));}
 @Test public void badIdentityRejected(){for(String tree:new String[]{null,"","/storage/file","https://server/path"})try{AutoCloudBackupPolicy.key(1,1,2,1,tree);fail();}catch(IllegalArgumentException expected){}}
 @Test public void manualAndAutoGateNeverWaitOrStealOwner(){Object first=new Object(),second=new Object();assertTrue(CloudBackupLease.acquire(first));try{assertFalse(CloudBackupLease.acquire(second));CloudBackupLease.release(second);assertFalse(CloudBackupLease.acquire(second));}finally{CloudBackupLease.release(first);}assertTrue(CloudBackupLease.acquire(second));CloudBackupLease.release(second);}
}
